'use strict';
const $=id=>document.getElementById(id);
let frameId=null,viewer3d=null,sceneLoading=null,sceneHost=null,flatHost=null,columnMetrics=null;
const state={dark:document.documentElement.dataset.theme==='dark',angle:60,length:30,orientation:0,mirror:1,progress:0,compare:false,view3d:true,surface:'tube',diameter:60,deformation:100,grid:true,axis:true,labels:true,playing:false};
const rad=d=>d*Math.PI/180;
function metrics(angle,length){const c=Math.cos(rad(angle));const ratio=Math.sqrt(5-4*c);const transverseBefore=2*length*Math.sin(rad(angle)),transverseAfter=transverseBefore/ratio;return{transverseBefore,transverseAfter,transverseLoss:transverseBefore-transverseAfter,transverseReduction:(1-1/ratio)*100,ratio,gain:(ratio-1)*100,newLength:length*ratio,extra:length*(ratio-1),axisAngle:Math.acos(Math.min(1,Math.abs((1-2*c)/ratio)))*180/Math.PI};}
function geometry(angle){const c=Math.cos(rad(angle)),s=Math.sin(rad(angle)),n=Math.sqrt(5-4*c);const y=(c-.5)/n,x=Math.sqrt(Math.max(0,.25-y*y));return{initial:{A:[0,-.5],B:[0,.5],C:[s,c-.5],D:[-s,.5-c]},final:{A:[0,-n/2],B:[0,n/2],C:[x,y],D:[-x,-y]}};}
function lerp(a,b,t){return a+(b-a)*t;}
// Congruent triangles rotate and translate; no scaling or vertex morphing.
function rigidTriangle(start,end,t){const center=p=>[p.reduce((v,q)=>v+q[0],0)/3,p.reduce((v,q)=>v+q[1],0)/3];const a=center(start),b=center(end);const edge=p=>Math.atan2(p[1][1]-p[0][1],p[1][0]-p[0][0]);let rotation=edge(end)-edge(start);while(rotation>Math.PI)rotation-=2*Math.PI;while(rotation<-Math.PI)rotation+=2*Math.PI;const r=rotation*t,cs=Math.cos(r),sn=Math.sin(r);return start.map(p=>{const x=p[0]-a[0],y=p[1]-a[1];return[lerp(a[0],b[0],t)+x*cs-y*sn,lerp(a[1],b[1],t)+x*sn+y*cs];});}
const svgStyle=`.flapA{fill:#b7dccb;fill-opacity:.86;stroke:#448b70;stroke-width:1.8;stroke-linejoin:round}.flapB{fill:#aec9df;fill-opacity:.86;stroke:#618cab;stroke-width:1.8;stroke-linejoin:round}.cut{fill:none;stroke:#31594a;stroke-width:2.4;stroke-linecap:round;stroke-linejoin:round}.original{fill:none;stroke:#9aaba0;stroke-width:1.4;stroke-dasharray:5 6}.annotation{font:11px sans-serif;fill:#879c8c}.point{fill:#426952}.point-label{font:11px sans-serif;fill:#62816c}.flap-label{font:500 20px sans-serif;fill:#356d56}.flap-label-b{fill:#507896}.dim{stroke:#9aafa0;stroke-width:1;fill:none}.dim-label{font:12px sans-serif;fill:#718a78}.angle-arc{stroke:#729886;stroke-width:1;fill:none}.angle-label{font:12px sans-serif;fill:#5c816b}`;
function diagram(t,options={}){const angle=options.angle??state.angle,len=state.length,m=metrics(angle,len),g=geometry(angle),I=g.initial,F=g.final;const w=760,h=450,scale=2.65*len;const tr1=rigidTriangle([I.A,I.B,I.C],[F.D,F.B,F.C],t),tr2=rigidTriangle([I.A,I.B,I.D],[F.A,F.C,F.D],t);const o=rad(state.orientation),cs=Math.cos(o),sn=Math.sin(o);const pt=p=>{let x=p[0]*state.mirror*scale,y=p[1]*scale;return[380+x*cs-y*sn,216+x*sn+y*cs];};const str=p=>pt(p).map(v=>v.toFixed(2)).join(',');const poly=p=>p.map(str).join(' ');const centroid=p=>[p.reduce((v,q)=>v+q[0],0)/3,p.reduce((v,q)=>v+q[1],0)/3];let a=pt(centroid(tr1)),b=pt(centroid(tr2));const marker=(point,label)=>{const [x,y]=pt(point);return`<circle class="point" cx="${x}" cy="${y}" r="3"/><text class="point-label" x="${x+9}" y="${y-8}">${label}</text>`;};let marks='';if(state.labels){if(t===0)marks=Object.entries(I).map(([k,v])=>marker(v,k)).join('');if(t===1)marks=Object.entries(F).map(([k,v])=>marker(v,k+'′')).join('');if(t===0){const r=.2;const p1=pt([0,-.5+r]),p2=pt([r*Math.sin(rad(angle)),-.5+r*Math.cos(rad(angle))]);const lab=pt([.25*Math.sin(rad(angle/2)),-.5+.25*Math.cos(rad(angle/2))]);marks+=`<path class="angle-arc" d="M${p1.join(',')} A${r*scale},${r*scale} 0 0 ${state.mirror<0?1:0} ${p2.join(',')}"/><text class="angle-label" x="${lab[0]+8}" y="${lab[1]+3}">${angle}°</text>`;}}
let incision='';if(t===0)incision=`<polyline class="cut" points="${poly([I.C,I.A,I.B,I.D])}"/>`;else if(t===1)incision=`<polyline class="cut" points="${poly([F.A,F.C,F.D,F.B])}"/>`;else incision=`<polyline class="cut" points="${poly([tr1[2],tr1[0],tr1[1]])}"/><polyline class="cut" points="${poly([tr2[0],tr2[1],tr2[2]])}"/>`;
const dimension=t===0?len:m.newLength;const half=t===0?scale/2:scale*m.ratio/2;let dim='';if((t===0||t===1)&&state.labels){dim=`<path class="dim" d="M570 ${216-half}h15 M570 ${216+half}h15 M578 ${216-half}V${216+half}"/><text class="dim-label" x="592" y="221">${dimension.toFixed(1)} mm</text>`;const transverse=t===0?m.transverseBefore:m.transverseAfter,halfWidth=transverse*scale/len/2;dim+=`<path class="dim" d="M${380-halfWidth} 399v12 M${380+halfWidth} 399v12 M${380-halfWidth} 405H${380+halfWidth}"/><text class="dim-label" x="380" y="421" text-anchor="middle">W ${transverse.toFixed(1)} mm</text>`;}
const markup = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${w} ${h}" role="img" aria-label="${angle} 度 Z-plasty ${t===0?'切口設計':t===1?'轉位完成':'皮瓣轉位'}"><title>Z-plasty：${angle}°，${len} mm，轉位 ${Math.round(t*100)}%</title><style>${svgStyle}</style><defs><pattern id="grid${options.id??'main'}" width="22" height="22" patternUnits="userSpaceOnUse"><circle cx="11" cy="11" r=".65" fill="#b3c4b0" opacity=".5"/></pattern><radialGradient id="tissue${options.id??'main'}"><stop stop-color="#e9eee0"/><stop offset="1" stop-color="#f4f6eb"/></radialGradient></defs><rect width="760" height="450" fill="#fcfdfa"/><rect x="123" y="28" width="514" height="380" rx="60" fill="url(#tissue${options.id??'main'})"/>${state.grid?`<rect x="123" y="28" width="514" height="380" rx="60" fill="url(#grid${options.id??'main'})"/>`:''}${state.axis?`<path class="original" d="M${str([0,-.68])} L${str([0,.68])}"/>`:''}<polygon class="flapB" points="${poly(tr2)}"/><polygon class="flapA" points="${poly(tr1)}"/>${incision}<text class="flap-label" x="${a[0]}" y="${a[1]+6}" text-anchor="middle">A</text><text class="flap-label flap-label-b" x="${b[0]}" y="${b[1]+6}" text-anchor="middle">B</text>${marks}<g transform="rotate(${state.orientation},380,216)">${dim}</g><text class="annotation" x="380" y="435" text-anchor="middle">${t===0?'等長三切口 · 對稱三角皮瓣':t===1?'皮瓣轉位完成 · 原始軸向延長':'皮瓣以剛體方式旋轉、平移 · 路徑為教學示意'}</text></svg>`;
return state.dark?markup.replace(/#b7dccb/g,'#487e6a').replace(/#aec9df/g,'#486b83').replace(/#448b70/g,'#80bda3').replace(/#618cab/g,'#88b4d1').replace(/#31594a/g,'#b5d7c4').replace(/#9aaba0/g,'#72897d').replace(/#879c8c/g,'#92a699').replace(/#426952/g,'#c0dfcd').replace(/#62816c/g,'#a6bfaf').replace(/#356d56/g,'#d2ebdc').replace(/#507896/g,'#d4e6f3').replace(/#9aafa0/g,'#7d9787').replace(/#718a78/g,'#a2b8a9').replace(/#729886/g,'#88b7a0').replace(/#5c816b/g,'#bdd6c5').replace(/#b3c4b0/g,'#647e6c').replace(/#e9eee0/g,'#283b31').replace(/#f4f6eb/g,'#202e26').replace(/#fcfdfa/g,'#18231e'):markup;}
function renderStage(){
 if(!sceneHost){$('stage').innerHTML='<div class="stage3d" id="sceneHost"><div class="scene-status"><span data-phase>正在載入 3D 皮瓣模型…</span><span data-lift></span><span data-column></span></div><div class="scene-toolbar"><div class="camera-presets"><button data-view="oblique" class="active" aria-pressed="true">斜視</button><button data-view="top" aria-pressed="false">俯視</button><button data-view="side" aria-pressed="false">側視</button></div><div class="scene-zoom"><button data-zoom-out aria-label="縮小 3D 模型">−</button><button data-zoom-in aria-label="放大 3D 模型">＋</button></div><label class="quality-label">畫質<select data-quality aria-label="3D 畫質"><option value="auto">自動</option><option value="low">省電</option><option value="normal">標準</option><option value="high">清晰</option></select></label></div><span class="camera-hint">拖曳旋轉 · 滾輪縮放 · 方向鍵調整視角</span></div><div id="flatHost"></div>';sceneHost=$('sceneHost');flatHost=$('flatHost');}
 const use3d=state.view3d&&!state.compare;sceneHost.hidden=!use3d;flatHost.hidden=use3d;
 if(use3d){
  $('stageTitle').textContent=state.surface==='tube'?'柱狀皮膚 — 曲面皮瓣轉位':'平面皮膚 — 立體皮瓣轉位';
  if(viewer3d){viewer3d.setActive(true);viewer3d.update(state);}
  else if(!sceneLoading){sceneLoading=import('./scene3d.js').then(m=>{columnMetrics=m.columnMeasurements;renderColumnMetrics();viewer3d=m.createFlap3D(sceneHost,{geometry,rigidTriangle},msg=>{toast(msg);state.view3d=false;render();});viewer3d.setActive(state.view3d&&!state.compare);viewer3d.update(state);}).catch(e=>{console.warn('3D initialization unavailable:',e);state.view3d=false;render();toast('此裝置無法啟用 WebGL 3D，已切換為 2D 幾何。');});}
 }else{
  if(viewer3d)viewer3d.setActive(false);
  if(state.compare){flatHost.innerHTML=`<div class="compare-grid"><div>${diagram(0,{id:'before'})}<p class="comparison-label">轉位前</p></div><div>${diagram(1,{id:'after'})}<p class="comparison-label">轉位後</p></div></div>`;$('stageTitle').textContent='2D 前後比較 — 相同比例';}
  else{flatHost.innerHTML=diagram(state.progress/100);$('stageTitle').textContent=state.progress===0?'01 — 切口設計':state.progress===100?'03 — 轉位完成':'02 — 皮瓣轉位';}
 }
 renderColumnMetrics();$('progress').value=state.progress;$('progressOut').textContent=Math.round(state.progress)+'%';
}

function renderColumnMetrics(){$('columnMeasures').hidden=state.surface!=='tube';if(!columnMetrics)return;const v=columnMetrics(state);$('columnLength').innerHTML=`${v.initialLength.toFixed(1)} → ${v.length.toFixed(1)} <small>mm</small>`;$('columnDiameter').innerHTML=`${v.initialDiameter.toFixed(1)} → ${v.diameter.toFixed(1)} <small>mm</small>`;$('columnCircumference').innerHTML=`${v.initialCircumference.toFixed(1)} → ${v.circumference.toFixed(1)} <small>mm</small>`;}
function render(){$('diameterOut').textContent=state.diameter.toFixed(0)+' mm';$('tubeDiameter').value=state.diameter;$('deformation').value=state.deformation;$('deformationOut').textContent=state.deformation+'%';$('deformControl').hidden=state.surface!=='tube';$('diameterControl').hidden=state.surface!=='tube';for(const [id,active]of [['tubeSurface',state.surface==='tube'],['planeSurface',state.surface==='plane']]){$(id).classList.toggle('active',active);$(id).setAttribute('aria-pressed',active);}const m=metrics(state.angle,state.length);['angle','length','orientation'].forEach(k=>{$(k).value=state[k];const input=$(k),pct=(state[k]-Number(input.min))/(Number(input.max)-Number(input.min))*100;input.style.background=`linear-gradient(to right, #18725d ${pct}%, ${state.dark?'#3a5141':'#e5ece6'} ${pct}%)`;});$('angleOut').textContent=state.angle+'°';$('lengthOut').textContent=state.length+' mm';$('orientationOut').textContent=state.orientation+'°';$('transverseLength').innerHTML=m.transverseAfter.toFixed(1)+' <small>mm</small>';$('transverseBefore').textContent=m.transverseBefore.toFixed(1);$('transverseAfter').textContent=m.transverseAfter.toFixed(1);$('transverseReduction').textContent='減少 '+m.transverseLoss.toFixed(1)+' mm（'+m.transverseReduction.toFixed(1)+'%）';$('gain').textContent=m.gain.toFixed(1);$('newLength').innerHTML=m.newLength.toFixed(1)+' <small>mm</small>';$('extraLength').innerHTML='+'+m.extra.toFixed(1)+' <small>mm</small>';$('originalLength').textContent=state.length.toFixed(1);$('finalLength').textContent=m.newLength.toFixed(1);$('rotation').innerHTML=m.axisAngle.toFixed(1)+'<small>°</small>';$('longBar').style.width=(m.ratio/2.3*100)+'%';document.querySelector('.length-bars div:first-child').style.width=(100/2.3)+'%';document.querySelectorAll('[data-angle]').forEach(el=>el.classList.toggle('active',+el.dataset.angle===state.angle));for(const [id,active] of [['normal',state.mirror===1],['mirror',state.mirror===-1]]){$(id).classList.toggle('active',active);$(id).setAttribute('aria-pressed',active);}for(const [id,active]of [['simTab',state.view3d&&!state.compare],['flatTab',!state.view3d&&!state.compare],['compareTab',state.compare]]){$(id).classList.toggle('active',active);$(id).setAttribute('aria-selected',active);}$('stageWrap').setAttribute('aria-labelledby',state.compare?'compareTab':state.view3d?'simTab':'flatTab');$('play').disabled=state.compare;$('progress').disabled=state.compare;document.querySelectorAll('[data-progress]').forEach(el=>el.disabled=state.compare);const curve=Array.from({length:61},(_,i)=>[i*3.2+4,49-metrics(i+30,1).gain/3].join(',')).join(' ');const x=(state.angle-30)*3.2+4,y=49-m.gain/3;$('miniChart').innerHTML=`<path d="M4 49H198" stroke="#e3e9dd"/><polyline points="${curve}" fill="none" stroke="#95bba1" stroke-width="1.7"/><circle cx="${x}" cy="${y}" r="3.5" fill="#18725d"/>`;renderStage();if(!state.playing)stop();}
function stop(){if(frameId!==null)cancelAnimationFrame(frameId);frameId=null;state.playing=false;$('playIcon').textContent='▶';$('playText').textContent=state.progress===100?'重新播放':'播放轉位';}
function setAngle(a){stop();state.angle=a;state.progress=0;render();}
['angle','length','orientation'].forEach(k=>$(k).addEventListener('input',e=>{stop();state[k]=+e.target.value;render();}));['grid','axis','labels'].forEach(k=>$(k).addEventListener('change',e=>{state[k]=e.target.checked;renderStage();}));$('planeSurface').onclick=()=>{stop();state.surface='plane';state.view3d=true;state.compare=false;render();};$('tubeSurface').onclick=()=>{stop();state.surface='tube';state.view3d=true;state.compare=false;render();};$('tubeDiameter').oninput=e=>{stop();state.diameter=+e.target.value;render();};$('deformation').oninput=e=>{stop();state.deformation=+e.target.value;render();};$('normal').onclick=()=>{state.mirror=1;render();};$('mirror').onclick=()=>{state.mirror=-1;render();};document.querySelectorAll('.presets button').forEach(el=>el.onclick=()=>setAngle(+el.dataset.angle));$('progress').oninput=e=>{stop();state.progress=+e.target.value;renderStage();};document.querySelectorAll('[data-progress]').forEach(el=>el.onclick=()=>{stop();state.progress=+el.dataset.progress;renderStage();stop();});$('simTab').onclick=()=>{stop();state.compare=false;state.view3d=true;render();};$('flatTab').onclick=()=>{stop();state.compare=false;state.view3d=false;render();};$('compareTab').onclick=()=>{stop();state.compare=true;render();};
$('play').onclick=()=>{if(state.playing){stop();return;}if(state.progress===100)state.progress=0;state.playing=true;$('playIcon').textContent='Ⅱ';$('playText').textContent='暫停';let last=null,lastDraw=0;function frame(now){if(!state.playing)return;if(last!==null)state.progress=Math.min(100,state.progress+(now-last)/65);last=now;if(now-lastDraw>33||state.progress===100){renderStage();lastDraw=now;}if(state.progress<100)frameId=requestAnimationFrame(frame);else stop();}frameId=requestAnimationFrame(frame);};
$('reset').onclick=()=>{stop();Object.assign(state,{angle:60,length:30,orientation:0,mirror:1,progress:0,compare:false,view3d:true,surface:'tube',diameter:60,deformation:100,grid:true,axis:true,labels:true});['grid','axis','labels'].forEach(k=>$(k).checked=true);render();};
const cardAngles=[30,45,60,75];$('angleCards').innerHTML=cardAngles.map(a=>{const m=metrics(a,30),g=geometry(a).initial,p=q=>`${41+q[0]*40},${32+q[1]*40}`;return`<button class="angle-card ${a===60?'active':''}" data-angle="${a}" aria-label="設定 ${a} 度，理論延長 ${m.gain.toFixed(1)} 百分比"><div class="card-top"><strong>${a}°</strong>${a===60?'<span>經典角度</span>':''}</div><div class="card-content"><svg viewBox="0 0 82 64" aria-hidden="true"><polygon points="${[g.A,g.B,g.C].map(p).join(' ')}" fill="#b7dccb" stroke="#82ad92"/><polygon points="${[g.A,g.B,g.D].map(p).join(' ')}" fill="#aec9df" stroke="#86a5b5"/><polyline points="${[g.C,g.A,g.B,g.D].map(p).join(' ')}" fill="none" stroke="#527f64" stroke-width="1.5"/></svg><div>理論延長<strong>+${m.gain.toFixed(1)}<small>%</small></strong></div></div></button>`;}).join('');document.querySelectorAll('.angle-card').forEach(el=>el.onclick=()=>setAngle(+el.dataset.angle));
const guideText=`<h2>讓幾何，動起來。</h2><ol><li>調整皮瓣角度與中央切口長度。三個切口保持等長，兩側角度保持對稱。</li><li>在「3D 皮瓣」拖曳畫面可旋轉視角，使用斜視、俯視、側視按鈕快速切換。3D 匯出為 PNG，2D 匯出為 SVG。</li><li>按下「播放轉位」，或拖曳時間軸查看任意時刻。綠色與藍色分別代表兩片皮瓣。</li><li>切換「前後比較」，以相同比例比較切口設計與完成狀態；右側顯示理論結果。</li><li>「切口方向」旋轉整體設計；「鏡像 Z」改變轉位方向。匯出可取得 3D 畫面或含參數的 2D 圖示。</li></ol><p>角落小字位置標記 A、B、C、D 表示幾何端點；皮瓣內的大寫 A、B 表示皮瓣身分。完成時的撇號（′）表示端點的新位置。</p>`;
const modelText=`<h2>模型與參考資料</h2><p>此工具模擬對稱、等長的單一 Z-plasty。2D 模式保留理想平面幾何；3D 模式加入游離皮瓣的彎曲抬升、交錯轉位、落回與周圍皮膚的連續變形。未切開的基底邊緣保持連接，游離端離開原位置。3D 可切換平面與柱狀皮膚。柱狀模型把平面座標沿圓柱展開，皮瓣沿曲面法向抬升與落回；實心柱體原始長度固定 180 mm，柱徑 D 獨立調整。切口與皮瓣按 mm 比例改變大小，視角不隨切口長度自動縮放。右側延長率仍是展開平面上的理想幾何值，並非圓柱上的直線距離。柱體形變以理論新增軸向長度為基礎，套用可調強度的簡化軸向伸長與徑向收縮，維持柱體容積；這只是可視化規則，不是經驗證的組織力學模型。抬升高度、厚度與變形路徑都是教學示意，不是實際手術操作順序或組織力學計算。</p><h3>軸向延長</h3><code>L′ = L × √(5 − 4 cos θ)<br>延長率 = (L′ / L − 1) × 100%</code><p>L′ 是原始攣縮軸線兩端在轉位後的距離，並非新中央縫合線的長度。60° 的精確結果為 √3 倍（約 73.2%）；常見教材以約 75% 表述。</p><h3>橫向寬度</h3><code>W = 2L sin θ<br>W′ = W / √(5 − 4 cos θ)</code><p>W 為兩個側切口端點在垂直於原始軸方向上的投影跨度，W′ 為轉位後的對應跨度。這是展開平面的幾何寬度。下方「柱體當前尺寸」則依示意形變顯示柱長、橫截面直徑與周長；周長為 πD。</p><h3>新舊中央軸線夾角</h3><code>φ = arccos(|1 − 2 cos θ| / √(5 − 4 cos θ))</code><p>此介面以無方向直線的較小夾角（0–90°）呈現。60° 為 90°。切口方向與鏡像只改變圖示朝向，不影響延長率。</p><h3>模型適用範圍</h3><p>30–90° 用於幾何探索，並非角度選擇建議。模型未計算皮膚彈性、組織張力、血流與三維變形；理論延長量不等於個別臨床結果。</p><h3>效能與畫質</h3><p>3D 僅在操作、播放或尺寸改變時渲染，閒置時停止。離開頁面或模型移出畫面會暫停動畫。手機預設採較低解析度與網格密度；可選「省電」降低負載，或切回 2D。效能仍取決於裝置 GPU、瀏覽器與電源狀態。</p><h3>參考資料</h3><p><a href="https://pmc.ncbi.nlm.nih.gov/articles/PMC2772284/" target="_blank" rel="noopener">Ellur & Guido (2009), A mathematical model to predict the change in direction of the common limb in Z plasty ↗</a></p><p><a href="https://www.aafp.org/afp/2003/0601/p2329" target="_blank" rel="noopener">Salam & Amin (2003), The Basic Z-Plasty ↗</a></p>`;
function showDialog(content){$('guideContent').innerHTML=content;$('guide').showModal();}$('openGuide').onclick=()=>showDialog(guideText);$('openModel').onclick=()=>showDialog(modelText);$('angleInfo').onclick=()=>showDialog(modelText);$('closeGuide').onclick=()=>$('guide').close();$('guide').onclick=e=>{if(e.target===$('guide')){const r=$('guide').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('guide').close();}};
let toastTimer;function toast(msg){$('toast').textContent=msg;$('toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),2500);}
$('expand').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await $('stageWrap').requestFullscreen();}catch{toast('此瀏覽器不支援全螢幕顯示。');}};
$('export').onclick=async()=>{if(state.view3d&&!state.compare&&viewer3d){const blob=await viewer3d.snapshot();if(!blob){toast('無法擷取 3D 畫面，請再試一次。');return;}const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`z-plasty-3d-${state.angle}deg-${Math.round(state.progress)}pct.png`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);toast('已匯出 3D 畫面 PNG。');return;}const m=metrics(state.angle,state.length);const content=state.compare?`<g>${diagram(0,{id:'export0'}).replace('<svg ','<svg x="0" y="55" width="760" height="450" ')}</g><g>${diagram(1,{id:'export1'}).replace('<svg ','<svg x="760" y="55" width="760" height="450" ')}</g>`:diagram(state.progress/100,{id:'export'}).replace('<svg ','<svg x="0" y="55" width="760" height="450" ');const w=state.compare?1520:760;const out=`<svg xmlns="http://www.w3.org/2000/svg" width="${w}" height="560" viewBox="0 0 ${w} 560"><rect width="100%" height="100%" fill="#fcfdfa"/><text x="24" y="32" fill="#18725d" font-family="sans-serif" font-size="18">Z-plasty Lab · θ ${state.angle}° · L ${state.length} mm · ${state.compare?'Before / After':Math.round(state.progress)+'%'}</text>${content}<text x="24" y="535" fill="#718a78" font-family="sans-serif" font-size="12">Ideal geometry · +${m.gain.toFixed(1)}% · ${m.newLength.toFixed(1)} mm · Educational illustration</text></svg>`;const url=URL.createObjectURL(new Blob([out],{type:'image/svg+xml;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`z-plasty-${state.angle}deg-${state.length}mm.svg`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('已匯出 SVG 圖示。');};
render();

function renderTheme(){document.documentElement.dataset.theme=state.dark?'dark':'light';$('themeToggle').setAttribute('aria-pressed',String(state.dark));$('themeToggle').setAttribute('aria-label',state.dark?'切換淺色主題':'切換深色主題');$('themeToggle').innerHTML=state.dark?'<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5"/></svg>':'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M20.5 14.2A8.5 8.5 0 0 1 9.8 3.5a8.5 8.5 0 1 0 10.7 10.7Z"/></svg>';render();}
$('themeToggle').onclick=()=>{state.dark=!state.dark;try{localStorage.setItem('zplasty-theme',state.dark?'dark':'light');}catch{}renderTheme();};
renderTheme();

document.addEventListener('visibilitychange',()=>{if(document.hidden)stop();});
new IntersectionObserver(entries=>{if(!entries[0].isIntersecting&&state.playing)stop();},{threshold:0}).observe($('stage'));
